import { Component, OnInit, OnDestroy, inject, PLATFORM_ID, ElementRef, ViewChild, signal } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { RouterLink } from '@angular/router';
import { CursorService } from '../../../../core/services/cursor.service';
import { ScrollService } from '../../../../core/services/scroll.service';

@Component({
  selector: 'app-hero',
  standalone: true,
  imports: [RouterLink],
  templateUrl: './hero.component.html',
  styleUrl: './hero.component.scss'
})
export class HeroComponent implements OnInit, OnDestroy {
  @ViewChild('heroRef') heroRef!: ElementRef<HTMLElement>;
  @ViewChild('reelVideo') reelVideo?: ElementRef<HTMLVideoElement>;
  private platformId = inject(PLATFORM_ID);
  cursor = inject(CursorService);
  scroll = inject(ScrollService);

  currentSlide = signal(0);
  videoPlaying = signal(true);
  private interval?: ReturnType<typeof setInterval>;
  private readonly onPointerMove = (e: MouseEvent) => {
    const x = (e.clientX / window.innerWidth - 0.5) * 20;
    const y = (e.clientY / window.innerHeight - 0.5) * 20;
    document.querySelectorAll('.hero-parallax').forEach((el: Element) => {
      const speed = Number((el as HTMLElement).dataset['speed'] || '1');
      (el as HTMLElement).style.transform = `translate(${x * speed}px, ${y * speed}px)`;
    });
  };

  slides = [
    { image: 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?w=1920&q=85', label: 'Wedding', title: 'Where Love', subtitle: 'Becomes Art' },
    { image: 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=1920&q=85', label: 'Portrait', title: 'Timeless', subtitle: 'Elegance' },
    { image: 'https://images.unsplash.com/photo-1469334031218-e382a71b716b?w=1920&q=85', label: 'Fashion', title: 'Cinematic', subtitle: 'Vision' },
  ];

  ngOnInit() {
    if (!isPlatformBrowser(this.platformId)) return;
    this.interval = setInterval(() => {
      this.currentSlide.update(v => (v + 1) % this.slides.length);
    }, 5500);
    this.initParallax();
  }

  ngOnDestroy() {
    clearInterval(this.interval);
    if (isPlatformBrowser(this.platformId)) window.removeEventListener('mousemove', this.onPointerMove);
  }

  private initParallax() {
    window.addEventListener('mousemove', this.onPointerMove, { passive: true });
  }

  goToSlide(i: number) { this.currentSlide.set(i); }

  toggleVideo() {
    const video = this.reelVideo?.nativeElement;
    if (!video) return;
    if (video.paused) {
      video.play().then(() => this.videoPlaying.set(true)).catch(() => this.videoPlaying.set(false));
    } else {
      video.pause();
      this.videoPlaying.set(false);
    }
  }
}
